        titleTemplate: "\u0627\u0635\u0644\u0627\u062D \u0642\u0631\u0627\u0631\u062F\u0627\u062F \u062B\u0628\u062A \u0634\u062F",
        messageTemplate: "\u0627\u0635\u0644\u0627\u062D \u0642\u0631\u0627\u0631\u062F\u0627\u062F {{contractNumber}} \u062B\u0628\u062A \u0648 \u0628\u0631\u0627\u06CC \u0628\u0631\u0631\u0633\u06CC \u062D\u0633\u0627\u0628\u062F\u0627\u0631\u06CC \u0622\u0645\u0627\u062F\u0647 \u0634\u062F.",
